import{_ as i,c as a,o as e,ag as r}from"./chunks/framework.B1jFR3yW.js";const _=JSON.parse('{"title":"操作系统","description":"","frontmatter":{},"headers":[],"relativePath":"计划/计算机基础/操作系统.md","filePath":"计划/计算机基础/操作系统.md"}'),o={name:"计划/计算机基础/操作系统.md"};function t(h,l,u,d,n,c){return e(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="操作系统" tabindex="-1">操作系统 <a class="header-anchor" href="#操作系统" aria-label="Permalink to &quot;操作系统&quot;">​</a></h1><blockquote><p>目标不是研究内核，而是理解服务为什么会卡、为什么会崩、为什么部署后和本地表现不一样。</p></blockquote><h2 id="你需要掌握什么" tabindex="-1">你需要掌握什么 <a class="header-anchor" href="#你需要掌握什么" aria-label="Permalink to &quot;你需要掌握什么&quot;">​</a></h2><h3 id="_1-进程、线程、协程" tabindex="-1">1. 进程、线程、协程 <a class="header-anchor" href="#_1-进程、线程、协程" aria-label="Permalink to &quot;1. 进程、线程、协程&quot;">​</a></h3><ul><li>进程和线程的区别</li><li>用户态和内核态的基本概念</li><li>多进程、多线程各自适合什么场景</li><li>协程解决了什么问题，和线程的差异是什么</li><li>Node.js 单线程事件循环为什么也能处理高并发 IO</li></ul><p>你至少要能回答：</p><ul><li>一个服务启动后，操作系统是如何管理它的</li><li>为什么会出现僵尸进程、孤儿进程</li><li>为什么 CPU 打满不一定是“请求多”，也可能是死循环或频繁上下文切换</li></ul><h3 id="_2-内存管理" tabindex="-1">2. 内存管理 <a class="header-anchor" href="#_2-内存管理" aria-label="Permalink to &quot;2. 内存管理&quot;">​</a></h3><ul><li>虚拟内存的基本概念</li><li>栈、堆分别是什么</li><li>内存分配和回收的大致过程</li><li>内存泄漏、内存溢出、频繁 GC 的区别</li><li>页面缓存、进程内存、磁盘空间不是一回事</li></ul><p>你至少要能处理：</p><ul><li>服务为什么越跑越占内存</li><li>容器或服务器为什么会 OOM</li><li>为什么机器还有空闲内存，但程序还是报错</li></ul><h3 id="_3-文件系统" tabindex="-1">3. 文件系统 <a class="header-anchor" href="#_3-文件系统" aria-label="Permalink to &quot;3. 文件系统&quot;">​</a></h3><ul><li>文件、目录、路径、挂载的概念</li><li>绝对路径和相对路径</li><li>文件描述符是什么</li><li>标准输入、标准输出、标准错误</li><li>日志文件为什么会不断增长，如何切分和清理</li></ul><p>你至少要理解：</p><ul><li>为什么上传、缓存、日志、数据库最终都会落到文件系统</li><li>为什么磁盘满了会导致服务异常</li></ul><h3 id="_4-io-与网络基础" tabindex="-1">4. IO 与网络基础 <a class="header-anchor" href="#_4-io-与网络基础" aria-label="Permalink to &quot;4. IO 与网络基础&quot;">​</a></h3><ul><li>同步 IO、异步 IO、阻塞、非阻塞</li><li>网络请求从发起到响应的大致过程</li><li>TCP 的连接、断开、重传、拥塞基本概念</li><li>常见网络问题：超时、连接拒绝、DNS 解析失败、端口占用</li></ul><p>你至少要会排查：</p><ul><li>服务启动了但访问不到</li><li>本地能调通，线上超时</li><li>接口偶发慢、文件上传慢、数据库连接慢</li></ul><h3 id="_5-并发与锁" tabindex="-1">5. 并发与锁 <a class="header-anchor" href="#_5-并发与锁" aria-label="Permalink to &quot;5. 并发与锁&quot;">​</a></h3><ul><li>竞争条件是什么</li><li>临界区是什么</li><li>互斥锁、读写锁、信号量了解其作用即可</li><li>死锁出现的原因</li></ul><p>这部分对你做这些事情很重要：</p><ul><li>处理定时任务重复执行</li><li>避免多个请求同时修改同一份数据</li><li>理解数据库事务和锁为什么会阻塞</li></ul><h3 id="_6-权限与隔离" tabindex="-1">6. 权限与隔离 <a class="header-anchor" href="#_6-权限与隔离" aria-label="Permalink to &quot;6. 权限与隔离&quot;">​</a></h3><ul><li>用户、用户组、权限位</li><li>进程以谁的身份运行</li><li>为什么同一个命令不同用户执行结果不同</li><li>环境变量是怎么影响程序运行的</li><li>容器、虚拟机、宿主机的基本隔离关系</li></ul><h3 id="_7-启动、运行、退出" tabindex="-1">7. 启动、运行、退出 <a class="header-anchor" href="#_7-启动、运行、退出" aria-label="Permalink to &quot;7. 启动、运行、退出&quot;">​</a></h3><ul><li>一个程序从启动到退出经历了什么</li><li>前台进程、后台进程</li><li>守护进程的概念</li><li>信号机制，如 <code>SIGTERM</code>、<code>SIGKILL</code></li><li>服务优雅退出为什么重要</li></ul><h2 id="对个人开发者最实用的落地方向" tabindex="-1">对个人开发者最实用的落地方向 <a class="header-anchor" href="#对个人开发者最实用的落地方向" aria-label="Permalink to &quot;对个人开发者最实用的落地方向&quot;">​</a></h2><h3 id="第一阶段" tabindex="-1">第一阶段 <a class="header-anchor" href="#第一阶段" aria-label="Permalink to &quot;第一阶段&quot;">​</a></h3><ul><li>看懂进程、线程、内存、文件系统的基本概念</li><li>能用系统命令观察 CPU、内存、磁盘、网络状态</li><li>能理解常见报错背后的系统原因</li></ul><h3 id="第二阶段" tabindex="-1">第二阶段 <a class="header-anchor" href="#第二阶段" aria-label="Permalink to &quot;第二阶段&quot;">​</a></h3><ul><li>把 Node.js、数据库、Nginx、Docker 的运行过程和操作系统概念对应起来</li><li>学会根据现象判断是代码问题、系统问题还是环境问题</li></ul><h3 id="第三阶段" tabindex="-1">第三阶段 <a class="header-anchor" href="#第三阶段" aria-label="Permalink to &quot;第三阶段&quot;">​</a></h3><ul><li>能独立定位线上慢请求、内存泄漏、端口冲突、磁盘打满、进程异常退出等问题</li></ul><h2 id="判断自己是否掌握" tabindex="-1">判断自己是否掌握 <a class="header-anchor" href="#判断自己是否掌握" aria-label="Permalink to &quot;判断自己是否掌握&quot;">​</a></h2><ul><li>能解释“服务为什么会挂”</li><li>能解释“为什么会慢”</li><li>能解释“为什么本地正常、线上异常”</li><li>能把问题定位到 CPU、内存、磁盘、网络、权限、配置中的某一类</li></ul>',36)])])}const b=i(o,[["render",t]]);export{_ as __pageData,b as default};
